import{_ as i,o as s,c as a,a2 as t}from"./chunks/framework.mRCPFc5l.js";const k=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"projects/steve/getting_started.md","filePath":"projects/steve/getting_started.md","lastUpdated":1787695050000}'),n={name:"projects/steve/getting_started.md"};function o(l,e,r,h,p,d){return s(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><nav class="table-of-contents"><ul><li><a href="#install-script">Install Script</a></li><li><a href="#dependencies">Dependencies</a></li><li><a href="#discord-developer-portal">Discord Developer Portal</a></li><li><a href="#download-files">Download Files</a></li><li><a href="#installation">Installation</a></li><li><a href="#database-setup">Database Setup</a></li><li><a href="#running-the-bot">Running the bot</a></li><li><a href="#additional-configuration">Additional Configuration</a></li></ul></nav><p>The following document is a tutorial on how to host the bot yourself. Click <a href="https://discord.com/oauth2/authorize?client_id=773117222380896276&amp;permissions=2147502080&amp;scope=applications.commands%20bot" target="_blank" rel="noreferrer">here</a> to invite the bot if you do not wish to self host.</p><h2 id="install-script" tabindex="-1">Install Script <a class="header-anchor" href="#install-script" aria-label="Permalink to &quot;Install Script&quot;">​</a></h2><p>A script is available <a href="https://raw.githubusercontent.com/nathanlytang/Steve/master/scripts/setup.sh" target="_blank" rel="noreferrer">here</a> for Linux installations. If you are using Windows or do not wish to use this script, skip to the next section.</p><p>To use this script, run this command with <strong>root access</strong>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wget</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -q</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/nathanlytang/Steve/master/scripts/setup.sh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./setup.sh</span></span></code></pre></div><p><strong>NOTE</strong>: The Discord application still must be created manually on the <a href="https://discord.com/developers/applications" target="_blank" rel="noreferrer">Discord Developer Portal</a>. The guide on setting up a Discord application can be found <a href="#discord-developer-portal">here</a>.</p><p>This script is also a configuration script, and can be run to change your environment configuration. Note that database names cannot be changed in MySQL after they have been created.</p><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h2><ul><li>Node.js <code>v12</code> or higher with npm</li><li>MySQL <code>8</code> or higher <strong>or</strong> MariaDB <code>v10.5</code> or higher</li><li>A Windows or Linux (Ubuntu and Debian tested) environment to run the bot</li></ul><h2 id="discord-developer-portal" tabindex="-1">Discord Developer Portal <a class="header-anchor" href="#discord-developer-portal" aria-label="Permalink to &quot;Discord Developer Portal&quot;">​</a></h2><p>To run a Discord bot, you must have a Discord application with the correct permissions, which can be created in the <a href="https://discord.com/developers/applications" target="_blank" rel="noreferrer">Discord Developer Portal</a>.</p><ol><li>On the top right of the site, click <code>New Application</code>. Give your application a name and click <code>Create</code></li><li>After the new application is created, select it and you will see a new screen with a <em>Settings</em> sidebar on the left. Open the <strong>Bot</strong> settings and click <code>Add Bot</code>.</li><li>Under the <em>Build-A-Bot</em> section in the <strong>Bot</strong> settings, click on <code>Reveal Token</code>. Copy this token, you will need it later in the guide.</li><li>In <strong>OAuth2</strong> settings, select the <em>bot</em> scope with <em>Send Messages</em> and <em>Embed Links</em> permissions. A link that looks like this <code>https://discord.com/api/oauth2/authorize?client_id=YOUR_BOT_CLIENT_ID&amp;permissions=18432&amp;scope=bot</code> will appear, this is the link you will use to invite your bot to your Discord servers.</li><li>Invite the bot to your server.</li></ol><p><strong>NOTE</strong>: Do not share your Discord token publicly as it can be used maliciously to impersonate your bot. If you suspect your token is compromised, click <code>Regenerate</code> to assign a new token to your bot.</p><h2 id="download-files" tabindex="-1">Download Files <a class="header-anchor" href="#download-files" aria-label="Permalink to &quot;Download Files&quot;">​</a></h2><p>Download a zip of the repository <a href="https://github.com/nathanlytang/Steve/archive/master.zip" target="_blank" rel="noreferrer">here</a> or use git to clone.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Change directory (Assuming you are using Linux)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Clone the Git repository from Github</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/nathanlytang/Steve.git/</span></span></code></pre></div><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>Once the required files are installed, we need to install the Node.js dependencies and copy the environment variables file.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Change directory (Assuming you are using Linux)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/Steve/</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Copy the environment variables file</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Install node.js dependencies</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><p>Edit the <code>.env</code> file in a text editor. Place your Discord token that you grabbed earlier into the DISCORD_TOKEN variable. Right click on the bot in your Discord server member list and click &quot;Copy ID&quot;, then paste into the CLIENT_ID variable. Below is the file you will edit:</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CLIENT_ID</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=&lt;YOUR_BOT_CLIENT_ID&gt;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DISCORD_TOKEN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=&lt;YOUR_DISCORD_BOT_TOKEN_HERE&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DB_HOST</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=127.0.0.1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DB_PORT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=3306</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DB_DATABASE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=stevebot</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DB_USERNAME</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=stevebotuser</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DB_PASSWORD</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=&lt;DATABASE_PASSWORD_HERE&gt;</span></span></code></pre></div><p><strong>Note</strong>: Remove the <code>&lt;</code> and <code>&gt;</code> signs when pasting your Discord token.</p><h2 id="database-setup" tabindex="-1">Database Setup <a class="header-anchor" href="#database-setup" aria-label="Permalink to &quot;Database Setup&quot;">​</a></h2><p>Steve stores all its information in a database. To set one up, follow <a href="./db_setup">this short guide</a>. Once the database has been setup, return here to continue.</p><p>Next, we will edit the <code>.env</code> file again. This time, take the password you just created during database setup and edit this line with your new password:</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DB_PASSWORD</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=&lt;DATABASE_PASSWORD_HERE&gt;</span></span></code></pre></div><h2 id="running-the-bot" tabindex="-1">Running the bot <a class="header-anchor" href="#running-the-bot" aria-label="Permalink to &quot;Running the bot&quot;">​</a></h2><p>The formal set up is complete! All you need to do to start the bot is run the following command in the terminal:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production</span></span></code></pre></div><h2 id="additional-configuration" tabindex="-1">Additional Configuration <a class="header-anchor" href="#additional-configuration" aria-label="Permalink to &quot;Additional Configuration&quot;">​</a></h2><p>Refer <a href="./additional_configuration">here</a> for additional configuration, including backups, and setting up background processes/autostart.</p>`,33)])])}const g=i(n,[["render",o]]);export{k as __pageData,g as default};
